import os,json,struct,pathlib
src='inputs/chall/Carmine-Falcone.raw';magic=b'\xff Go buildinf:'; hits=[]
with open(src,'rb') as f:
 prev=b'';n=0
 while True:
  c=f.read(16*1024*1024)
  if not c:break
  b=prev+c;base=n-len(prev);pos=0
  while True:
   j=b.find(magic,pos)
   if j<0:break
   off=base+j
   if not hits or off!=hits[-1]:hits.append(off)
   pos=j+1
  n+=len(c);prev=b[-32:]
 def varstr(b,p):
  v=0;s=0
  for i in range(10):
   z=b[p];p+=1;v|=(z&127)<<s
   if not z&128:return b[p:p+v].decode('utf8','replace'),p+v
   s+=7
  raise ValueError('badvarint')
 rows=[]
 for off in hits:
  f.seek(off);b=f.read(16384);r={'offset':off,'header_hex':b[:32].hex(),'ptr_size':b[14],'flags':b[15]}
  if b[15]&2:
   try:r['version'],p=varstr(b,32);r['module'],p=varstr(b,p)
   except Exception as e:r['parse_error']=str(e)
  else:r['pointer_fields_hex']=b[16:32].hex()
  r['context_ascii']=''.join(chr(x) if 32<=x<127 or x in (9,10,13) else '.' for x in b[:8192]);rows.append(r)
pathlib.Path(os.environ['OUT'],'go_buildinfo.json').write_text(json.dumps({'size':n,'hits':rows},indent=2))
print('image_bytes',n,'buildinfo_hits',len(rows))
for r in rows:print(r['offset'],r['ptr_size'],r['flags'],r.get('version'),r.get('module','')[:200])
